PHRASES: dict[str, dict[str, str]] = {"fr": _FR, "es": _ES, "de": _DE}


def phrase(language: str, english: str) -> str:
    """`english` in `language`'s table, or `english` itself."""
    return PHRASES.get(language.split("-", 1)[0], {}).get(english, english)


def enum_phrase(language: str, kind: str, value: str) -> str:
    """A contract's enum value said in `language` (`complexity: medium` → `moyenne`), or the value itself."""
    return PHRASES.get(language.split("-", 1)[0], {}).get(f"{kind}: {value}", value)
